import base64, urllib.parse

raw = ""

s = base64.b64decode(raw).decode()
d = urllib.parse.parse_qs(s)
code = d["code"][0]
state = d.get("state", [""])[0]
expected = "e6ff2a92-4d77-4e2e-a312-d16db4686a28"
print("STATE:", state)
print("MATCH:", state == expected)
assert state == expected, f"state mismatch: {state}"
with open(r"deploy\_aws_code.txt", "w", encoding="utf-8") as f:
    f.write(code)
print("written code len:", len(code))
